6: # Video Transcript Downloader
7: 
8: `./scripts/vtd.js` can:
9: - Print a transcript as a clean paragraph (timestamps optional).
10: - Download video/audio/subtitles.
11: 
12: Transcript behavior:
13: - YouTube: fetch via `youtube-transcript-plus` when possible.
14: - Otherwise: pull subtitles via `yt-dlp`, then clean into a paragraph.
15: 
16: ## Setup
17: 
18: ```bash
19: cd ~/Projects/agent-scripts/skills/video-transcript-downloader && npm ci
20: ```
21: 
22: CLI syntax:
23: 
24: ```bash
25: ./scripts/vtd.js --help
26: ./scripts/vtd.js transcript --help
27: ```
28: 
29: Subcommands support focused help without requiring `--url`.
30: 
31: ## Transcript (default: clean paragraph)
32: 
33: ```bash
34: ./scripts/vtd.js transcript --url 'https://…'
35: ./scripts/vtd.js transcript --url 'https://…' --lang en
36: ./scripts/vtd.js transcript --url 'https://…' --timestamps
37: ./scripts/vtd.js transcript --url 'https://…' --keep-brackets
38: ```
39: 
40: ## Download video / audio / subtitles
41: 
42: ```bash
43: ./scripts/vtd.js download --url 'https://…' --output-dir ~/Downloads
44: ./scripts/vtd.js audio --url 'https://…' --output-dir ~/Downloads
45: ./scripts/vtd.js subs --url 'https://…' --output-dir ~/Downloads --lang en
46: ```
47: 
48: ## Formats (list + choose)
49: 
50: List available formats (format ids, resolution, container, audio-only, etc):
51: 
52: ```bash
53: ./scripts/vtd.js formats --url 'https://…'
54: ```
55: 
56: Download a specific format id (example):
57: 
58: ```bash
59: ./scripts/vtd.js download --url 'https://…' --output-dir ~/Downloads -- --format 137+140
60: ```
61: 
62: Prefer MP4 container without re-encoding (remux when possible):
63: 
64: ```bash
65: ./scripts/vtd.js download --url 'https://…' --output-dir ~/Downloads -- --remux-video mp4
66: ```
67: 
68: ## Notes
69: 
70: - Default transcript output is a single paragraph. Use `--timestamps` only when asked.
71: - Bracketed cues like `[Music]` are stripped by default; keep them via `--keep-brackets`.
72: - Pass extra `yt-dlp` args after `--` for `transcript` fallback, `download`, `audio`, `subs`, `formats`.
73: 
74: ```bash
75: ./scripts/vtd.js formats --url 'https://…' -- -v
76: ```
77: 
78: ## Troubleshooting (only when needed)
79: 
80: - Missing `yt-dlp` / `ffmpeg`:
81: 
82: ```bash
83: brew install yt-dlp ffmpeg
84: ```
85: 
86: - Verify:
87: 
88: ```bash
89: yt-dlp --version
90: ffmpeg -version | head -n 1
91: ```", "scripts/vtd.js": "1: #!/usr/bin/env node
2: import { spawn } from "node:child_process";
3: import fs from "node:fs";
4: import os from "node:os";
5: import path from "node:path";
6: import { fileURLToPath } from "node:url";
7: 
8: import { YoutubeTranscript } from "youtube-transcript-plus";
9: 
10: const __filename = fileURLToPath(import.meta.url);
11: const __dirname = path.dirname(__filename);
12: 
13: function die(message, code = 1) {
14:   process.stderr.write(String(message).trimEnd() + "\n");
15:   process.exit(code);
16: }
17: 
18: function parseArgs(argv) {
19:   // Tiny no-deps parser.
20:   // - `--flag` => boolean
21:   // - `--key value`
22:   // - `--` => forward remaining args to yt-dlp
23:   const positional = [];
24:   const opts = {};
25:   let i = 0;
26:   while (i < argv.length) {
27:     const a = argv[i];
28:     if (a === "--") {
29:       opts.extra = argv.slice(i + 1);
30:       break;
31:     }
32:     if (!a.startsWith("--")) {
33:       positional.push(a);
34:       i += 1;
35:       continue;
36:     }
37:     const key = a.slice(2);
38:     const next = argv[i + 1];
39:     const isValue = next !== undefined && !next.startsWith("--");
40:     if (!isValue) {
41:       opts[key] = true;
42:       i += 1;
43:       continue;
44:     }
45:     if (opts[key] === undefined) opts[key] = next;
46:     else if (Array.isArray(opts[key])) opts[key].push(next);
47:     else opts[key] = [opts[key], next];
48:     i += 2;
49:   }
50:   return { positional, opts };
51: }
52: 
53: function toArray(v) {
54:   if (v === undefined) return [];
55:   if (Array.isArray(v)) return v;
56:   return [v];
57: }
58: 
59: function which(cmd) {
60:   // Avoid shelling out to `which`; keep it portable + fast.
61:   const envPath = process.env.PATH || "";
62:   const parts = envPath.split(path.delimiter);
63:   for (const p of parts) {
64:     const full = path.join(p, cmd);
65:     if (fs.existsSync(full)) return full;
66:   }
67:   return null;
68: }
69: 
70: function resolveBin(name, fallback) {
71:   return which(name) || (fallback && fs.existsSync(fallback) ? fallback : null);
72: }
73: 
74: function run(cmd, args, { cwd } = {}) {
75:   return new Promise((resolve) => {
76:     // Capture stdout + stderr to keep yt-dlp’s error context intact.
77:     const child = spawn(cmd, args, { cwd, stdio: ["ignore", "pipe", "pipe"] });
78:     let out = "";
79:     child.stdout.on("data", (d) => (out += d.toString()));
80:     child.stderr.on("data", (d) => (out += d.toString()));
81:     child.on("close", (code) => resolve({ code, out }));
82:   });
83: }
84: 
85: function isYouTubeUrl(url) {
86:   return /(^https?:\/\/)?(www\.)?(youtube\.com|youtu\.be)\//i.test(url);
87: }
88: 
89: function extractYouTubeId(input) {
90:   if (!input) return null;
91:   const raw = String(input).trim();
92:   if (/^[a-zA-Z0-9_-]{11}$/.test(raw)) return raw;
93:   const m = raw.match(/(?:v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
94:   return m ? m[1] : null;
95: }
96: 
97: function decodeHtmlEntities(input) {
98:   if (!input) return input;
99:   // Some transcripts come back double-encoded (e.g. "&amp;#39;").
100:   // Decode up to 2 passes; stop once stable.
101:   let text = input;
102:   for (let i = 0; i < 2; i++) {
103:     const decoded = text
104:       .replace(/&amp;/g, "&")
105:       .replace(/&lt;/g, "<")
106:       .replace(/&gt;/g, ">")
107:       .replace(/&quot;/g, '"')
108:       .replace(/&apos;/g, "'")
109:       .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(Number(dec)))
110:       .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCodePoint(parseInt(hex, 16)));
111:     if (decoded === text) break;
112:     text = decoded;
113:   }
114:   return text;
115: }
116: 
117: function formatTimestamp(seconds) {
118:   const s = Math.max(0, Math.floor(seconds));
119:   const h = Math.floor(s / 3600);
120:   const m = Math.floor((s % 3600) / 60);
121:   const sec = Math.floor(s % 60);
122:   if (h > 0) return `${h}:${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
123:   return `${m}:${String(sec).padStart(2, "0")}`;
124: }
125: 
126: function cleanSegments(segments, { keepBrackets } = {}) {
127:   const cleaned = [];
128:   let prev = "";
129: 
130:   for (const seg of segments) {
131:     const s = String(seg || "")
132:       .replace(/\s+/g, " ")
133:       .trim();
134:     if (!s) continue;
135: 
136:     // Subtitles often contain HTML-ish tags; strip them.
137:     const withoutTags = s.replace(/<[^>]+>/g, "").trim();
138:     const withoutBrackets = keepBrackets ? withoutTags : withoutTags.replace(/\[[^\]]*\]/g, "").trim();
139:     const withoutCurlies = withoutBrackets.replace(/\{[^}]+\}/g, "").replace(/♪/g, "").trim();
140:     const t = withoutCurlies.replace(/\s+/g, " ").trim();
141:     if (!t) continue;
142:     if (t === prev) continue;
143:     // Dedup heuristic: captions often repeat previous line with a longer suffix.
144:     if (prev && t.startsWith(prev)) {
145:       const newPart = t.slice(prev.length).trim();
146:       if (newPart) cleaned.push(newPart);
147:     } else if (prev && t.includes(prev)) {
148:       // Another common pattern: current line contains previous line in the middle.
149:       const idx = t.indexOf(prev);
150:       const newPart = (t.slice(0, idx) + t.slice(idx + prev.length)).trim();
151:       if (newPart) cleaned.push(newPart);
152:     } else {
153:       cleaned.push(t);
154:     }
155:     prev = t;
156:   }
157: 
158:   return cleaned;
159: }
160: 
161: function toParagraph(segments, { keepBrackets } = {}) {
162:   const cleaned = cleanSegments(segments, { keepBrackets });
163:   return cleaned.join(" ").replace(/\s+/g, " ").trim();
164: }
165: 
166: function parseSrt(text) {
167:   const lines = String(text).split(/\r?\n/);
168:   const segments = [];
169:   for (const line of lines) {
170:     const l = line.trim();
171:     if (!l) continue;
172:     if (/^\d+$/.test(l)) continue;
173:     if (l.includes("-->")) continue;
174:     segments.push(l);
175:   }
176:   return segments;
177: }
178: 
179: function parseVtt(text) {
180:   const lines = String(text).split(/\r?\n/);
181:   const segments = [];
182:   for (const line of lines) {
183:     const l = line.trim();
184:     if (!l) continue;
185:     if (l === "WEBVTT") continue;
186:     if (l.startsWith("Kind:") || l.startsWith("Language:")) continue;
187:     if (l.includes("-->")) continue;
188:     // cue settings like "align:start position:0%"
189:     if (/^(align|position|size|line):/i.test(l)) continue;
190:     // Remove inline timestamps like "<00:00:00.000>" (common in YouTube VTT).
191:     const cleaned = l.replace(/<\d{2}:\d{2}:\d{2}\.\d{3}>/g, "").trim();
192:     if (cleaned) segments.push(cleaned);
193:   }
194:   return segments;
195: }
196: 
197: async function ytDlpSubtitlesToTemp({ url, lang, ytdlpPath, extra }) {
198:   const ytdlp = ytdlpPath || resolveBin("yt-dlp", "/opt/homebrew/bin/yt-dlp");
199:   if (!ytdlp) die("missing yt-dlp; install `yt-dlp` and ensure it is on PATH");
200: 
201:   const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "vtd-subs-"));
202:   const outTemplate = path.join(tmpDir, "%(id)s.%(ext)s");
203: 
204:   const args = [];
205:   args.push(
206:     "--write-sub",
207:     "--write-auto-sub",
208:     "--skip-download",
209:     "--sub-lang",
210:     lang,
211:     "-o",
212:     outTemplate,
213:   );
214:   if (extra?.length) args.push(...extra);
215:   args.push(url);
216: 
217:   const r = await run(ytdlp, args);
218:   if (r.code !== 0) {
219:     fs.rmSync(tmpDir, { recursive: true, force: true });
220:     die(r.out.trim() || "yt-dlp subtitle download failed");
221:   }
222: 
223:   const files = fs
224:     .readdirSync(tmpDir)
225:     .map((f) => path.join(tmpDir, f))
226:     .filter((f) => /\.(vtt|srt|ass|ttml)$/i.test(f))
227:     .sort((a, b) => fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs);
228: 
229:   if (files.length === 0) {
230:     fs.rmSync(tmpDir, { recursive: true, force: true });
231:     die(`no subtitles found (lang=${lang})`);
232:   }
233: 
234:   return { tmpDir, subtitlePath: files[0] };
235: }
236: 
237: async function cmdTranscript({ url, lang, timestamps, keepBrackets, extra }) {
238:   if (!url) die("missing --url");
239: 
240:   if (isYouTubeUrl(url)) {
241:     const id = extractYouTubeId(url);
242:     if (id) {
243:       try {
244:         // Preferred path: direct transcript fetch (no yt-dlp / no files).
245:         const transcript = await YoutubeTranscript.fetchTranscript(id);
246:         if (timestamps) {
247:           for (const entry of transcript) {
248:             const ts = formatTimestamp(entry.offset / 1000);
249:             process.stdout.write(`[${ts}] ${decodeHtmlEntities(entry.text).replace(/\s+/g, " ").trim()}\n`);
250:           }
251:           return;
252:         }
253:         const paragraph = toParagraph(transcript.map((e) => decodeHtmlEntities(e.text)), { keepBrackets });
254:         if (!paragraph) die("empty transcript");
255:         process.stdout.write(paragraph + "\n");
256:         return;
257:       } catch {
258:         // Fallback below: use yt-dlp subtitles when direct transcript fails.
259:       }
260:     }
261:   }
262: 
263:   const { tmpDir, subtitlePath } = await ytDlpSubtitlesToTemp({
264:     url,
265:     lang,
266:     extra,
267:   });
268: 
269:   try {
270:     const raw = fs.readFileSync(subtitlePath, "utf8");
271:     const segments = subtitlePath.endsWith(".srt") ? parseSrt(raw) : parseVtt(raw);
272:     if (timestamps) {
273:       // Subtitle timestamps are inconsistent across sites; keep output stable here.
274:       const paragraph = toParagraph(segments, { keepBrackets });
275:       process.stdout.write(paragraph + "\n");
276:       return;
277:     }
278:     const paragraph = toParagraph(segments, { keepBrackets });
279:     if (!paragraph) die("empty transcript from subtitles");
280:     process.stdout.write(paragraph + "\n");
281:   } finally {
282:     fs.rmSync(tmpDir, { recursive: true, force: true });
283:   }
284: }
285: 
286: async function cmdSubs({ url, lang, outputDir, extra }) {
287:   if (!url) die("missing --url");
288: 
289:   const { tmpDir, subtitlePath } = await ytDlpSubtitlesToTemp({
290:     url,
291:     lang,
292:     extra,
293:   });
294: 
295:   try {
296:     const out = path.resolve(outputDir);
297:     fs.mkdirSync(out, { recursive: true });
298:     const dest = path.join(out, path.basename(subtitlePath));
299:     fs.copyFileSync(subtitlePath, dest);
300:     process.stdout.write(dest + "\n");
301:   } finally {
302:     fs.rmSync(tmpDir, { recursive: true, force: true });
303:   }
304: }
305: 
306: async function cmdDownload({ url, outputDir, extra }) {
307:   if (!url) die("missing --url");
308:   const ytdlp = resolveBin("yt-dlp", "/opt/homebrew/bin/yt-dlp");
309:   if (!ytdlp) die("missing yt-dlp; install `yt-dlp` and ensure it is on PATH");
310: 
311:   const out = path.resolve(outputDir);
312:   fs.mkdirSync(out, { recursive: true });
313: 
314:   const args = [];
315: 
316:   // `--print after_move:filepath` gives the final path after merges/remux.
317:   args.push("-P", out, "-o", "%(title).200B (%(id)s).%(ext)s", "-S", "res,ext:mp4:m4a,tbr", "--print", "after_move:filepath");
318:   if (extra?.length) args.push(...extra);
319:   args.push(url);
320: 
321:   const r = await run(ytdlp, args);
322:   if (r.code !== 0) die(r.out.trim() || "yt-dlp download failed");
323: 
324:   const lines = r.out.split("\n").map((l) => l.trim());
325:   const filePath = lines.find((l) => l.startsWith("/") && fs.existsSync(l));
326:   if (!filePath) die(r.out.trim() || "could not determine downloaded file path");
327:   process.stdout.write(path.resolve(filePath) + "\n");
328: }
329: 
330: async function cmdAudio({ url, outputDir, extra }) {
331:   if (!url) die("missing --url");
332:   const ytdlp = resolveBin("yt-dlp", "/opt/homebrew/bin/yt-dlp");
333:   if (!ytdlp) die("missing yt-dlp; install `yt-dlp` and ensure it is on PATH");
334:   const ffmpeg = resolveBin("ffmpeg", "/opt/homebrew/bin/ffmpeg");
335:   if (!ffmpeg) die("missing ffmpeg; install `ffmpeg` (needed for audio extraction)");
336: 
337:   const out = path.resolve(outputDir);
338:   fs.mkdirSync(out, { recursive: true });
339: 
340:   const args = [];
341: 
342:   args.push(
343:     "--ffmpeg-location",
344:     ffmpeg,
345:     "-P",
346:     out,
347:     "-o",
348:     "%(title).200B (%(id)s).%(ext)s",
349:     "-x",
350:     "--audio-format",
351:     "mp3",
352:     "--print",
353:     "after_move:filepath",
354:   );
355:   if (extra?.length) args.push(...extra);
356:   args.push(url);
357: 
358:   const r = await run(ytdlp, args);
359:   if (r.code !== 0) die(r.out.trim() || "yt-dlp audio failed");
360: 
361:   const lines = r.out.split("\n").map((l) => l.trim());
362:   const filePath = lines.find((l) => l.startsWith("/") && fs.existsSync(l));
363:   if (!filePath) die(r.out.trim() || "could not determine downloaded file path");
364:   process.stdout.write(path.resolve(filePath) + "\n");
365: }
366: 
367: async function cmdFormats({ url, extra }) {
368:   if (!url) die("missing --url");
369:   const ytdlp = resolveBin("yt-dlp", "/opt/homebrew/bin/yt-dlp");
370:   if (!ytdlp) die("missing yt-dlp; install `yt-dlp` and ensure it is on PATH");
371: 
372:   // Print raw yt-dlp format table; user picks `--format <id>` for downloads.
373:   const args = ["-F"];
374:   if (extra?.length) args.push(...extra);
375:   args.push(url);
376: 
377:   const r = await run(ytdlp, args);
378:   if (r.code !== 0) die(r.out.trim() || "yt-dlp formats failed");
379:   process.stdout.write(r.out);
380: }
381: 
382: function usage(command) {
383:   const rel = path.relative(process.cwd(), path.join(__dirname, "vtd.js"));
384:   const lines = {
385:     transcript: [
386:       "usage:",
387:       `  ${rel} transcript --url 'https://…' [--lang en] [--timestamps] [--keep-brackets] [-- <yt-dlp extra…>]`,
388:       "",
389:       "flags:",
390:       "  --url URL          video URL",
391:       "  --lang CODE        subtitle language (default: en)",
392:       "  --timestamps       print timestamps when available",
393:       "  --keep-brackets    keep bracketed cues like [Music]",
394:     ],
395:     download: [
396:       "usage:",
397:       `  ${rel} download --url 'https://…' [--output-dir ~/Downloads] [-- <yt-dlp extra…>]`,
398:       "",
399:       "flags:",
400:       "  --url URL          video URL",
401:       "  --output-dir DIR   output directory",
402:     ],
403:     audio: [
404:       "usage:",
405:       `  ${rel} audio --url 'https://…' [--output-dir ~/Downloads] [-- <yt-dlp extra…>]`,
406:       "",
407:       "flags:",
408:       "  --url URL          video URL",
409:       "  --output-dir DIR   output directory",
410:     ],
411:     subs: [
412:       "usage:",
413:       `  ${rel} subs --url 'https://…' [--output-dir ~/Downloads] [--lang en] [-- <yt-dlp extra…>]`,
414:       "",
415:       "flags:",
416:       "  --url URL          video URL",
417:       "  --lang CODE        subtitle language (default: en)",
418:       "  --output-dir DIR   output directory",
419:     ],
420:     formats: [
421:       "usage:",
422:       `  ${rel} formats --url 'https://…' [-- <yt-dlp extra…>]`,
423:       "",
424:       "flags:",
425:       "  --url URL          video URL",
426:     ],
427:   };
428:   if (command && lines[command]) return lines[command].join("\n");
429:   return [
430:     "usage:",
431:     `  ${rel} transcript --url 'https://…' [--lang en] [--timestamps] [--keep-brackets] [-- <yt-dlp extra…>]`,
432:     `  ${rel} download   --url 'https://…' [--output-dir ~/Downloads] [-- <yt-dlp extra…>]`,
433:     `  ${rel} audio      --url 'https://…' [--output-dir ~/Downloads] [-- <yt-dlp extra…>]`,
434:     `  ${rel} subs       --url 'https://…' [--output-dir ~/Downloads] [--lang en] [-- <yt-dlp extra…>]`,
435:     `  ${rel} formats    --url 'https://…' [-- <yt-dlp extra…>]`,
436:   ].join("\n");
437: }
438: 
439: async function main() {
440:   const { positional, opts } = parseArgs(process.argv.slice(2));
441:   const cmd = positional[0];
442: 
443:   if (!cmd || cmd === "help" || cmd === "-h" || cmd === "--help") {
444:     process.stdout.write(usage() + "\n");
445:     return;
446:   }
447: 
448:   if (opts.help || positional[1] === "help" || positional[1] === "-h" || positional[1] === "--help") {
449:     process.stdout.write(usage(cmd) + "\n");
450:     return;
451:   }
452: 
453:   const url = opts.url;
454:   const lang = opts.lang || "en";
455:   const outputDir = opts["output-dir"] || path.join(os.homedir(), "Downloads");
456: 
457:   const timestamps = Boolean(opts.timestamps);
458:   const keepBrackets = Boolean(opts["keep-brackets"]);
459:   const extra = opts.extra || [];
460: 
461:   if (cmd === "transcript") {
462:     await cmdTranscript({ url, lang, timestamps, keepBrackets, extra });
463:     return;
464:   }
465:   if (cmd === "download") {
466:     await cmdDownload({ url, outputDir, extra });
467:     return;
468:   }
469:   if (cmd === "audio") {
470:     await cmdAudio({ url, outputDir, extra });
471:     return;
472:   }
473:   if (cmd === "subs") {
474:     await cmdSubs({ url, lang, outputDir, extra });
475:     return;
476:   }
477:   if (cmd === "formats") {
478:     await cmdFormats({ url, extra });
479:     return;
480:   }
481: 
482:   die(`unknown command: ${cmd}\n\n${usage()}`);
483: }
484: 
485: main().catch((e) => die(e?.stack || e?.message || String(e)));"}}

